import * as tf from '@tensorflow/tfjs';
import { Transformer } from '@tensorflow-models/transformer';

async function main() {
    // Load the BlenderBot model
    const model = await Transformer.load('facebook/blenderbot-400m-distill');

    // Function to generate response
    async function generateResponse(inputText) {
        const outputTokens = await model.generate({
            text: [inputText],
            maxOutputLength: 50,
            numReturnSequences: 1
        });

        return outputTokens[0].text;
    }

    // Example usage
