// Function to calculate the rounded rectangle points
function roundRect(size, radius) {
    var w = Math.min(size[0], size[1]);
    var h = Math.max(size[0], size[1]);

    if (w <= 2 * radius || h <= 2 * radius) return null;

    var points = [];
