    points.push([x + w - radius, y + h - radius]);
    points.push([x + w - radius, y + h]);

    // Bottom-left corner
    points.push([x + radius, y + h]);
    points.push([x, y + h - radius]);
    points.push([x + radius, y + h - radius]);

