            // Copy headers and footers from the first document
            foreach (var section in mainPart1.Document.Body.Elements<SectionProperties>())
            {
                var headerReference = section.HeaderReference;
                var footerReference = section.FooterReference;

                if (headerReference != null && !string.IsNullOrEmpty(headerReference.Id.Value))
                {
                    var headerPart = mainPart1.GetPartById(headerReference.Id.Value);
                    CopyHeaderFooter(headerPart, outputFilePath, "header");
                }

                if (footerReference != null && !string.IsNullOrEmpty(footerReference.Id.Value))
                {
                    var footerPart = mainPart1.GetPartById(footerReference.Id.Value);
                    CopyHeaderFooter(footerPart, outputFilePath, "footer");
                }
            }

            // Copy styles from the first document
            CopyStyles(mainPart1, outputFilePath);

            // Copy the first two pages of content from the first document
            var body1 = mainPart1.Document.Body;
            var paragraphs1 = body1.Elements<Paragraph>();
            int count = 0;
            foreach (var paragraph in paragraphs1)
            {
                if (count >= 2) break;
                AddContent(paragraph, outputFilePath);
                count++;
            }
        }

        // Load the second document
        using (var doc2 = WordprocessingDocument.Open(sourceDoc2Path, false))
        {
            var mainPart2 = doc2.MainDocumentPart;
            if (mainPart2 == null) throw new Exception("The second document does not have a main part.");

            // Copy the rest of the content from the second document
            var body2 = mainPart2.Document.Body;
            var paragraphs2 = body2.Elements<Paragraph>();
            foreach (var paragraph in paragraphs2)
