            return False

        last_block = self.get_latest_block()
        new_block = Block(
            last_block.index + 1,
            last_block.hash,
            datetime.now(),
            self.pending_transactions,
            self.proof_of_work(last_block)
        )

        self.chain.append(new_block)
        self.pending_transactions = []

        # Distribute rewards to miners
        reward = sum([tx['amount'] for tx in self.pending_transactions])
        self.add_transaction(miner_address, 'mining_reward', reward)

        return True

    def add_transaction(self, sender, recipient, amount):
        transaction = {
            'sender': sender,
            'recipient': recipient,
            'amount': amount
        }
        self.pending_transactions.append(transaction)

    def proof_of_work(self, last_block):
        last_proof = last_block.proof
        last_hash = last_block.hash
        proof = 0
        while not self.valid_proof(last_proof, last_hash, proof):
            proof += 1
        return proof

    @staticmethod
    def valid_proof(last_proof, last_hash, proof):
        guess = f'{last_proof}{last_hash}{proof}'.encode()
        guess_hash = hashlib.sha256(guess).hexdigest()
        return guess_hash[:4] == "0000"

