### Vertex Shader

The vertex shader will pass the position of each vertex to the fragment shader. In this case, we'll use a flat color for simplicity, but you can modify it as needed.

```glsl
#version 330 core

layout(location = 0) in vec3 aPos;

out vec4 vColor;

void main()
{
    gl_Position = vec4(aPos, 1.0);
    vColor = vec4(1.0, 1.0, 1.0, 1.0); // White color
}
```

### Fragment Shader

The fragment shader will perform the actual raycasting calculations. This example assumes that the world is represented by a grid of tiles, where each tile has a certain height.

```glsl
#version 330 core

in vec4 vColor;
out vec4 FragColor;

uniform float uPlayerX; // Player's X position
uniform float uPlayerY; // Player's Y position
uniform float uPlayerAngle; // Player's facing angle in radians
uniform int uWorldWidth; // Width of the world in tiles
uniform int uWorldHeight; // Height of the world in tiles
uniform sampler2D uWorldTexture; // Texture containing the world data

const float FOV = 60.0 * PI / 180.0; // Field of view in radians
const float HALF_FOV = FOV / 2.0;
const float Z_NEAR = 0.1;
const float Z_FAR = 100.0;

float getTileHeight(int x, int y)
{
    return texture(uWorldTexture, vec2(x / float(uWorldWidth), y / float(uWorldHeight))).r;
}

vec3 castRay(float angle)
{
    float cosA = cos(angle);
    float sinA = sin(angle);

    float x = uPlayerX;
    float y = uPlayerY;

    float dx = cosA;
    float dy = sinA;

    while (true)
    {
        x += dx;
        y += dy;

        if (x < 0 || x >= uWorldWidth || y < 0 || y >= uWorldHeight)
            break;

        float tileHeight = getTileHeight(int(x), int(y));

        if (tileHeight > 0)
        {
            float distanceToWall = sqrt((x - uPlayerX) * (x - uPlayerX) + (y - uPlayerY) * (y - uPlayerY));
            return vec3(distanceToWall, tileHeight, 1.0);
        }
    }

    return vec3(Z_FAR, 0.0, 0.0);
}

void main()
{
    vec2 screenCoords = gl_FragCoord.xy / vec2(800, 600); // Assuming a 800x600 window
    float angle = uPlayerAngle - HALF_FOV + FOV * screenCoords.x;

    vec3 rayData = castRay(angle);

    float distanceToWall = rayData.x;
    float wallHeight = atan(rayData.y / distanceToWall) * 180.0 / PI;

    float lineHeight = abs(tan(wallHeight * PI / 180.0)) * 600.0 / distanceToWall;

    float startY = (600.0 - lineHeight) / 2.0;
    float endY = startY + lineHeight;

    if (startY < 0.0)
    {
        startY = 0.0;
        endY = lineHeight;
    }

    if (endY > 600.0)
    {
        endY = 600.0;
        lineHeight = 600.0 - startY;
    }

    for (int i = int(startY); i < int(endY); ++i)
    {
        FragColor = vec4(1.0, 1.0, 1.0, 1.0); // White color
    }
}
```

### Explanation

- **Vertex Shader**: Passes the position of each vertex to the fragment shader.
- **Fragment Shader**:
  - `getTileHeight`: Retrieves the height of a tile from a texture.
  - `castRay`: Simulates a ray being cast from the player's position at a given angle until it hits a wall or goes out of bounds.
  - The main function calculates the angle based on the screen coordinates, casts a ray, and determines the line height to draw on the screen.

