        int x = gid.x + i;
        if (x >= 0 && x < input.get_width()) {
            color += input.read({ x, gid.y }) * horizontalWeights[i + 2];
        }
    }

    // Normalize the color by dividing it with the weight sum
    color /= weightSum;

    // Apply the vertical pass
    weightSum = 0;
    for (int j = -2; j <= 2; ++j) {
        weightSum += verticalWeights[j + 2];
    }

    for (int j = -2; j <= 2; ++j) {
        int y = gid.y + j;
        if (y >= 0 && y < input.get_height()) {
            color += output.read({ gid.x, y }) * verticalWeights[j + 2];
        }
    }

    // Write the final blurred color back to the output texture
    output.write(color, gid);
}
