class Sprite {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.color = 'red';
    }

    draw(ctx) {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    updatePosition(newX, newY) {
        this.x = newX;
        this.y = newY;
    }
}

const canvas = document.getElementById('spriteCanvas');
const ctx = canvas.getContext('2d');

// Set canvas size to match window dimensions
function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

let sprites = [];

function renderSprites() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    sprites.forEach(sprite => sprite.draw(ctx));
}

document.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;

    // Add a new sprite at the clicked position
    sprites.push(new Sprite(mouseX, mouseY, 50, 50));

    renderSprites();
});

document.addEventListener('mousemove', (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;

    // Move all sprites to follow the mouse cursor
    sprites.forEach(sprite => {
        sprite.updatePosition(mouseX - sprite.width / 2, mouseY - sprite.height / 2);
    });

    renderSprites();
});
```

This code sets up a basic sprite editor that allows you to click anywhere on the canvas to add a red square (sprite), and then moves all sprites to follow your mouse cursor as it moves across the screen.

