```javascript
function findEntityInJson(jsonData, entityKey) {
    const results = [];

    // Helper function to perform recursive search
    function search(obj, path = '') {
        if (typeof obj === 'object' && obj !== null) {
            Object.entries(obj).forEach(([key, value]) => {
                const newPath = `${path}.${key}` || key;
                if (key === entityKey) {
                    results.push({ value: value, path: newPath });
                }
                search(value, newPath);
            });
        } else if (Array.isArray(obj)) {
            obj.forEach((item, index) => {
                const newPath = `${path}[${index}]`;
                search(item, newPath);
            });
        }
    }

    // Start searching from the root of the JSON data
    search(jsonData);

    return results;
}

// Example usage:
const jsonData = {
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "Anytown"
    },
    "hobbies": ["reading", "traveling"],
    "contact": {
        "email": "john@example.com",
        "phone": "+1-555-0199"
    }
};

const entityKeyToSearch = "email";
const result = findEntityInJson(jsonData, entityKeyToSearch);
console.log(result); // Output: [{ value: 'john@example.com', path: 'contact.email' }]
```

This function works by defining a helper `search` function that traverses the JSON object or array. When it encounters an object property matching the `entityKey`, it records the value and its path in the `results` array. This approach ensures that even deeply nested objects and arrays are searched thoroughly.

