Here's the complete code:

```rust
use std::fs;
use std::path::Path;
use reqwest::Url;
use serde_json::Value;
use tokio::runtime::Runtime;

fn main() {
    let rt = Runtime::new().unwrap();
    rt.block_on(async {
        // Read URLs from file
        let url_file_path = "urls.txt";
        let content = fs::read_to_string(url_file_path).expect("Unable to read file");
        let urls: Vec<String> = content.lines().map(|line| line.trim().to_string()).collect();

        // Separate YouTube URLs
        let mut youtube_urls = Vec::new();
        for url_str in &urls {
            if is_youtube_url(url_str).await {
                youtube_urls.push(url_str.clone());
            }
        }

        // Download YouTube URLs using yt-dlp
        for youtube_url in youtube_urls {
            println!("Downloading: {}", youtube_url);
            download_with_yt_dlp(&youtube_url).await.expect("Failed to download video");
        }
    });
}

async fn is_youtube_url(url_str: &str) -> bool {
    match Url::parse(url_str) {
        Ok(url) => url.host_str().map_or(false, |host| host == "www.youtube.com" || host == "youtu.be"),
        Err(_) => false,
    }
}

async fn download_with_yt_dlp(url: &str) -> Result<(), Box<dyn std::error::Error>> {
    let output_dir = "./downloads";
    let args = vec![
        "--output",
        format!("{}/%(title)s.%(ext)s", output_dir).as_str(),
        url,
    ];

    yt_dlp::download(args)?;
    Ok(())
}
```

